32 |     function withdraw(uint256 amount) public {
33 |         _totalSupply = _totalSupply.sub(amount);
34 |         _balances[msg.sender] = _balances[msg.sender].sub(amount);
35 |         uni.safeTransfer(msg.sender, amount);
36 |     }
